// TypeScript Version: 4.1

/**
* Interface describing constructor options.
*/
interface Options {
	/**
	* Bottom padding (in pixels). Default: 0.
	*/
	bottom?: number;

	/**
	* Left padding (in pixels). Default: 0.
	*/
	left?: number;

	/**
	* Right padding (in pixels). Default: 0.
	*/
	right?: number;

	/**
	* Top padding (in pixels). Default: 0.
	*/
	top?: number;
}

/**
* Interface describing a JSON-serialized padding instance.
*/
interface JSON {
	/**
	* Bottom padding (in pixels).
	*/
	bottom: number;

	/**
	* Left padding (in pixels).
	*/
	left: number;

	/**
	* Right padding (in pixels).
	*/
	right: number;

	/**
	* Top padding (in pixels).
	*/
	top: number;
}

/**
* Interface describing a padding instance.
*/
interface Padding {
	/**
	* Bottom padding (in pixels).
	*
	* @example
	* var padding = new Padding();
	*
	* padding.bottom = 10;
	*
	* var v = padding.bottom;
	* // returns 10
	*/
	bottom: number;

	/**
	* Left padding (in pixels).
	*
	* @example
	* var padding = new Padding();
	*
	* padding.left = 10;
	*
	* var v = padding.left;
	* // returns 10
	*/
	left: number;

	/**
	* List of enumerable properties.
	*
	* @example
	* var padding = new Padding();
	*
	* var v = padding.properties;
	* // returns [ 'bottom', 'left', 'right', 'top' ]
	*/
	readonly properties: Array<string>;

	/**
	* Right padding (in pixels).
	*
	* @example
	* var padding = new Padding();
	*
	* padding.right = 10;
	*
	* var v = padding.right;
	* // returns 10
	*/
	right: number;

	/**
	* Top padding (in pixels).
	*
	* @example
	* var padding = new Padding();
	*
	* padding.top = 10;
	*
	* var v = padding.top;
	* // returns 10
	*/
	top: number;

	/**
	* Serializes a padding instance to a JSON object.
	*
	* ## Notes
	*
	* -   This method is implicitly invoked by `JSON.stringify`.
	*
	* @returns JSON object
	*
	* @example
	* var padding = new Padding({
	*     'top': 10
	* });
	*
	* var v = padding.toJSON();
	* // returns { 'bottom': 0, 'left': 0, 'right': 0, 'top': 10 }
	*/
	toJSON(): JSON;
}

/**
* Interface defining a padding constructor which is both "newable" and "callable".
*/
interface Constructor {
	/**
	* Padding constructor.
	*
	* @param options - constructor options
	* @param options.bottom - bottom padding (in pixels) (default: 0)
	* @param options.left - left padding (in pixels) (default: 0)
	* @param options.right - right padding (in pixels) (default: 0)
	* @param options.top - top padding (in pixels) (default: 0)
	* @throws options argument must be an object
	* @throws must provide valid options
	* @returns padding instance
	*
	* @example
	* var padding = new Padding({
	*     'top': 10
	* });
	*
	* var v = padding.top;
	* // returns 10
	*/
	new ( options?: Options ): Padding;

	/**
	* Padding constructor.
	*
	* @param options - constructor options
	* @param options.bottom - bottom padding (in pixels) (default: 0)
	* @param options.left - left padding (in pixels) (default: 0)
	* @param options.right - right padding (in pixels) (default: 0)
	* @param options.top - top padding (in pixels) (default: 0)
	* @throws options argument must be an object
	* @throws must provide valid options
	* @returns padding instance
	*
	* @example
	* var padding = Padding({
	*     'top': 10
	* });
	*
	* var v = padding.top;
	* // returns 10
	*/
	( options?: Options ): Padding;
}

/**
* Padding constructor.
*
* @param options - constructor options
* @param options.bottom - bottom padding (in pixels) (default: 0)
* @param options.left - left padding (in pixels) (default: 0)
* @param options.right - right padding (in pixels) (default: 0)
* @param options.top - top padding (in pixels) (default: 0)
* @throws options argument must be an object
* @throws must provide valid options
* @returns padding instance
*
* @example
* var padding = new Padding();
* // returns <Padding>
*
* var v = padding.toJSON();
* // returns { 'bottom': 0, 'left': 0, 'right': 0, 'top': 0 }
*/
declare var ctor: Constructor;


// EXPORTS //

export = ctor;

// eslint-doctest-alias: Padding
